import {
  createSolidDataset,
  getSolidDataset,
  saveSolidDatasetAt,
  createContainerAt,
  getSourceUrl,
  isContainer,
  getContainedResourceUrlAll,
} from "@inrupt/solid-client";

export async function getOrCreateTodoList(containerUri, fetch) {
  try {
    // First check if the container exists
    try {
      const container = await getSolidDataset(containerUri, { fetch });
      if (!isContainer(container)) {
        throw new Error("Not a container");
      }
      // Container exists, proceed with index.ttl
    } catch (containerError) {
      // Container doesn't exist, create it
      if (containerError.statusCode === 404) {
        await createContainerAt(containerUri, { fetch });
      } else {
        throw containerError;
      }
    }
    
    // Now handle the index.ttl file
    const indexUrl = `${containerUri}index.ttl`;
    try {
      const todoList = await getSolidDataset(indexUrl, { fetch });
      return todoList;
    } catch (error) {
      if (error.statusCode === 404) {
        const todoList = await saveSolidDatasetAt(
          indexUrl,
          createSolidDataset(),
          {
            fetch,
          }
        );
        return todoList;
      }
      throw error;
    }
  } catch (error) {
    console.error("Error in getOrCreateTodoList:", error);
    throw error;
  }
}